/**
 * Wraps each HTTP attempt, inside the retry loop. Call `next(request)` to continue, or
 * return a `Response` of your own, e.g. from a cache. The first middleware is the outermost.
 */
export type Middleware = (
  request: Request,
  next: (request: Request) => Promise<Response>
) => Promise<Response>;

export function withMiddleware(
  base: typeof fetch | undefined,
  middleware: readonly Middleware[] | undefined
): typeof fetch | undefined {
  if (!middleware || middleware.length === 0) {
    return base;
  }
  const send = base ?? fetch;
  return (input, init) => {
    const chain = middleware.reduceRight<(request: Request) => Promise<Response>>(
      (next, current) => (request) => current(request, next),
      (request) => send(request)
    );
    return chain(new Request(input, init));
  };
}
